"""Scenario pairs for abgate.

Each pair is a (baseline_fn, candidate_fn) tuple of zero-argument
callables.
"""


def _sum_for_loop():
    total = 0
    for i in range(1_000_000):
        total += i
    return total


def _doubled_sum_for_loop():
    total = 0
    for i in range(1_000_000):
        total += i
    for i in range(1_000_000):
        total += i
    return total


def pass_case_baseline():
    return _sum_for_loop()


def pass_case_candidate():
    # builtin sum over the same data -- faster than the Python-level loop
    return sum(range(1_000_000))


pass_case = (pass_case_baseline, pass_case_candidate)


def fail_case_baseline():
    return _sum_for_loop()


def fail_case_candidate():
    # deliberately 2x slower via doubled work
    return _doubled_sum_for_loop()


fail_case = (fail_case_baseline, fail_case_candidate)

