import subprocess
import sys

import pytest

from abgate import ROUNDS, WARMUP, interleave


def _run_abgate(pair_name):
    return subprocess.run(
        [sys.executable, "abgate.py", "scenarios", pair_name],
        capture_output=True,
        text=True,
        timeout=120,
    )


class TestPassCase:
    def test_exit_zero(self):
        proc = _run_abgate("pass_case")
        assert proc.returncode == 0, proc.stdout + proc.stderr

    def test_stdout_contains_both_medians(self):
        proc = _run_abgate("pass_case")
        assert "baseline_median=" in proc.stdout
        assert "candidate_median=" in proc.stdout


class TestFailCase:
    def test_exit_two(self):
        proc = _run_abgate("fail_case")
        assert proc.returncode == 2, proc.stdout + proc.stderr

    def test_stdout_contains_both_medians(self):
        proc = _run_abgate("fail_case")
        assert "baseline_median=" in proc.stdout
        assert "candidate_median=" in proc.stdout


class TestInterleaving:
    def test_order_alternates_after_warmup(self):
        order = []

        def fn_a():
            order.append("A")

        def fn_b():
            order.append("B")

        interleave(fn_a, fn_b, rounds=ROUNDS, warmup=WARMUP)

        expected = ["A", "B"] * (WARMUP + ROUNDS)
        assert order == expected

    def test_lengths_and_call_counts(self):
        counts = {"a": 0, "b": 0}

        def fn_a():
            counts["a"] += 1

        def fn_b():
            counts["b"] += 1

        times_a, times_b = interleave(fn_a, fn_b)
        assert len(times_a) == ROUNDS
        assert len(times_b) == ROUNDS
        assert counts == {"a": WARMUP + ROUNDS, "b": WARMUP + ROUNDS}

    def test_timings_are_positive(self):
        times_a, times_b = interleave(lambda: None, lambda: None, rounds=3, warmup=1)
        assert all(t >= 0.0 for t in times_a + times_b)


if __name__ == "__main__":
    sys.exit(pytest.main([__file__, "-v"]))

